+	fn validators(&self) -> &[AuthorityId] {
+		self.validator_set.validators()
+	}
+
+	fn len(&self) -> usize {
+		self.validator_set.len()
+	}
+
+	fn weight(&self, authority: &AuthorityId) -> Option<VoteWeight> {
+		self.voting_weights.get(authority).copied()
