+    ExecutionFailure {
+        message: String,
+        counterexample: Option<(InputMap, Abi)>,
+        error_diagnostic: Option<FileDiagnostic>,
+    },
+    MinimizationFailure {
+        message: String,
+    },
+    ForeignCallFailure {
+        message: String,
+    },
+    CompileError(FileDiagnostic),
+}
+
+impl FuzzingRunStatus {
+    pub fn failed(&self) -> bool {
+        !matches!(
